#!/bin/bash
set -e

# === WoW Backup ===
# Databases backed up:
#   acore_auth        - CRITICAL: accounts
#   acore_characters  - CRITICAL: character progress
#
# Intentionally excluded:
#   acore_world       - auto-regenerated by worldserver on first start
#   acore_playerbots  - bot state only, acceptable to lose
#
# Retention (count-based, safe for irregular backup schedules):
#   Local backups:  keep last KEEP_LOCAL_COUNT
#   Drive backups:  keep last KEEP_DRIVE_COUNT

# === PATHS ===
FULL_BASE="/home/deck/azerothcore/backups"
SCREENSHOT_SRC="/home/deck/.steam/steam/userdata/1631191323/760/remote/15764481545068347392/screenshots"
GDRIVE_REMOTE="wow-backup:wow-backup"

# === SETTINGS ===
KEEP_LOCAL_COUNT=10   # Keep this many most-recent local backups
KEEP_DRIVE_COUNT=20   # Keep this many most-recent Drive backups

TIMESTAMP=$(date +%F_%H-%M)
BACKUP_DIR="$FULL_BASE/$TIMESTAMP"

# ── STEP 0: Stop servers ──────────────────────────────────────────────────────
echo
echo "[0/4] Stopping servers..."

if pgrep -x worldserver > /dev/null; then
  echo "  Stopping worldserver..."
  pkill -SIGINT -f "worldserver"
  echo "  Waiting for worldserver to shut down..."
  while pgrep -x worldserver > /dev/null; do
    sleep 1
  done
  echo "  ✅ worldserver stopped."
else
  echo "  worldserver not running — skipping."
fi

if pgrep -x authserver > /dev/null; then
  echo "  Stopping authserver..."
  pkill -SIGINT -f "authserver"
  echo "  Waiting for authserver to shut down..."
  while pgrep -x authserver > /dev/null; do
    sleep 1
  done
  echo "  ✅ authserver stopped."
else
  echo "  authserver not running — skipping."
fi

mkdir -p "$BACKUP_DIR" || { echo "Failed to create backup dir"; exit 1; }

echo "======================================="
echo "WoW Backup Started"
echo "Timestamp: $TIMESTAMP"
echo "Backup dir: $BACKUP_DIR"
echo "======================================="

# ── STEP 1: Dump databases ───────────────────────────────────────────────────
echo
echo "[1/4] Dumping databases..."

echo "  Dumping acore_auth..."
mysqldump --no-tablespaces -h 127.0.0.1 -u acore -pacore acore_auth \
  > "$BACKUP_DIR/acore_auth.sql" || { echo "Failed: acore_auth dump"; exit 1; }

echo "  Dumping acore_characters..."
mysqldump --no-tablespaces -h 127.0.0.1 -u acore -pacore acore_characters \
  > "$BACKUP_DIR/acore_characters.sql" || { echo "Failed: acore_characters dump"; exit 1; }

echo "  Saving progress report..."

{
  echo "=== Server Version ==="
  echo "AzerothCore last update: $(cd /home/deck/azerothcore && git log -1 --format='%ci')"
  echo "Playerbots last update: $(cd /home/deck/azerothcore/modules/mod-playerbots && git log -1 --format='%ci')"
  echo

  echo "=== Alliance ==="
  mysql -h 127.0.0.1 -u acore -pacore -N -e "
    SELECT
      CONCAT(
        c.name, ': ',
        CASE c.race
          WHEN 1 THEN 'Human' WHEN 3 THEN 'Dwarf' WHEN 4 THEN 'Night Elf'
          WHEN 7 THEN 'Gnome' WHEN 11 THEN 'Draenei' ELSE 'Unknown'
        END, ', ',
        CASE c.class
          WHEN 1 THEN 'Warrior' WHEN 2 THEN 'Paladin' WHEN 3 THEN 'Hunter'
          WHEN 4 THEN 'Rogue' WHEN 5 THEN 'Priest' WHEN 6 THEN 'Death Knight'
          WHEN 7 THEN 'Shaman' WHEN 8 THEN 'Mage' WHEN 9 THEN 'Warlock'
          WHEN 11 THEN 'Druid' ELSE 'Unknown'
        END,
        ' | Level: ', c.level,
        ' | Money: ', FLOOR(c.money / 10000), 'g',
        ' | Achievements: ', COALESCE(cap.total_points, 0), 'pts (', COALESCE(cap.total_achievements, 0), ')',
        ' | Played: ', FLOOR(c.totaltime / 3600), 'hrs'
      )
    FROM acore_characters.characters c
    JOIN acore_auth.account a ON c.account = a.id
    LEFT JOIN acore_characters.character_achievement_points cap ON cap.guid = c.guid
    WHERE a.username NOT LIKE 'RNDBOT%'
      AND c.race IN (1,3,4,7,11)
    ORDER BY c.totaltime DESC;
  "

  mysql -h 127.0.0.1 -u acore -pacore -N -e "
    SELECT CONCAT(
      'Total: Money: ', FLOOR(SUM(c.money) / 10000), 'g',
      ' | Achievements: ', COALESCE(SUM(cap.total_points), 0), 'pts (', COALESCE(SUM(cap.total_achievements), 0), ')',
      ' | Played: ', FLOOR(SUM(c.totaltime) / 3600), 'hrs'
    )
    FROM acore_characters.characters c
    JOIN acore_auth.account a ON c.account = a.id
    LEFT JOIN acore_characters.character_achievement_points cap ON cap.guid = c.guid
    WHERE a.username NOT LIKE 'RNDBOT%'
      AND c.race IN (1,3,4,7,11);
  "

  echo
  echo "=== Horde ==="
  mysql -h 127.0.0.1 -u acore -pacore -N -e "
    SELECT
      CONCAT(
        c.name, ': ',
        CASE c.race
          WHEN 2 THEN 'Orc' WHEN 5 THEN 'Undead' WHEN 6 THEN 'Tauren'
          WHEN 8 THEN 'Troll' WHEN 9 THEN 'Goblin' WHEN 10 THEN 'Blood Elf' ELSE 'Unknown'
        END, ', ',
        CASE c.class
          WHEN 1 THEN 'Warrior' WHEN 2 THEN 'Paladin' WHEN 3 THEN 'Hunter'
          WHEN 4 THEN 'Rogue' WHEN 5 THEN 'Priest' WHEN 6 THEN 'Death Knight'
          WHEN 7 THEN 'Shaman' WHEN 8 THEN 'Mage' WHEN 9 THEN 'Warlock'
          WHEN 11 THEN 'Druid' ELSE 'Unknown'
        END,
        ' | Level: ', c.level,
        ' | Money: ', FLOOR(c.money / 10000), 'g',
        ' | Achievements: ', COALESCE(cap.total_points, 0), 'pts (', COALESCE(cap.total_achievements, 0), ')',
        ' | Played: ', FLOOR(c.totaltime / 3600), 'hrs'
      )
    FROM acore_characters.characters c
    JOIN acore_auth.account a ON c.account = a.id
    LEFT JOIN acore_characters.character_achievement_points cap ON cap.guid = c.guid
    WHERE a.username NOT LIKE 'RNDBOT%'
      AND c.race IN (2,5,6,8,9,10)
    ORDER BY c.totaltime DESC;
  "

  mysql -h 127.0.0.1 -u acore -pacore -N -e "
    SELECT CONCAT(
      'Total: Money: ', FLOOR(SUM(c.money) / 10000), 'g',
      ' | Achievements: ', COALESCE(SUM(cap.total_points), 0), 'pts (', COALESCE(SUM(cap.total_achievements), 0), ')',
      ' | Played: ', FLOOR(SUM(c.totaltime) / 3600), 'hrs'
    )
    FROM acore_characters.characters c
    JOIN acore_auth.account a ON c.account = a.id
    LEFT JOIN acore_characters.character_achievement_points cap ON cap.guid = c.guid
    WHERE a.username NOT LIKE 'RNDBOT%'
      AND c.race IN (2,5,6,8,9,10);
  "

  echo
  echo "=== Grand Total ==="
  mysql -h 127.0.0.1 -u acore -pacore -N -e "
    SELECT CONCAT(
      'Money: ', FLOOR(SUM(c.money) / 10000), 'g',
      ' | Achievements: ', COALESCE(SUM(cap.total_points), 0), 'pts (', COALESCE(SUM(cap.total_achievements), 0), ')',
      ' | Played: ', FLOOR(SUM(c.totaltime) / 3600), 'hrs'
    )
    FROM acore_characters.characters c
    JOIN acore_auth.account a ON c.account = a.id
    LEFT JOIN acore_characters.character_achievement_points cap ON cap.guid = c.guid
    WHERE a.username NOT LIKE 'RNDBOT%';
  "
} > "$BACKUP_DIR/playtime_by_character.txt" || { echo "Failed: progress report export"; exit 1; }

echo "  Saving characters.json..."
REPO_DATA_DIR="/home/deck/wow-armory-data"

# Sync the clone to the latest published state before touching anything in
# it — both so the sticky-collectable merge below reads the true latest
# characters.json (not a stale local copy), and so the commit+push at the
# end of this step is always a clean fast-forward instead of colliding with
# whatever else has been pushed to main since the last backup run (code
# changes, a rename, etc. — this directory is purely an auto-managed
# publish target, never hand-edited, so discarding any local state here is
# always safe).
(cd "$REPO_DATA_DIR" && git fetch origin main && git reset --hard origin/main) \
  || echo "  Warning: failed to sync $REPO_DATA_DIR with origin/main before publishing (non-fatal)"

COLLECTION_GEAR_DEFS="$REPO_DATA_DIR/assets/data/collections/gear.json"
COLLECTION_MOUNTS_DEFS="$REPO_DATA_DIR/assets/data/collections/mounts.json"
COLLECTION_PETS_DEFS="$REPO_DATA_DIR/assets/data/collections/pets.json"
ACHIEVEMENTS_TMP="$(mktemp)"
EQUIPPED_TMP="$(mktemp)"
KNOWN_SPELLS_TMP="$(mktemp)"
mysql -h 127.0.0.1 -u acore -pacore -N -B -e "
  SELECT ca.guid, ca.achievement, ca.date
  FROM acore_characters.character_achievement ca
  JOIN acore_characters.characters c ON c.guid = ca.guid
  JOIN acore_auth.account a ON a.id = c.account
  WHERE a.username NOT LIKE 'RNDBOT%';
" > "$ACHIEVEMENTS_TMP"
mysql -h 127.0.0.1 -u acore -pacore -N -B -e "
  SELECT ci.guid, ii.itemEntry
  FROM acore_characters.character_inventory ci
  JOIN acore_characters.item_instance ii ON ii.guid = ci.item
  JOIN acore_characters.characters c ON c.guid = ci.guid
  JOIN acore_auth.account a ON a.id = c.account
  WHERE ci.bag = 0 AND ci.slot BETWEEN 0 AND 18
    AND a.username NOT LIKE 'RNDBOT%';
" > "$EQUIPPED_TMP"
# Only the spell ids that actually matter for Mounts/Pets detection — a
# max-level character can know thousands of spells, so filtering
# server-side keeps this cheap. Both categories share this one query.
SPELL_COLLECTION_IDS="$(python3 -c "
import json
ids = set()
for path in ('$COLLECTION_MOUNTS_DEFS', '$COLLECTION_PETS_DEFS'):
    with open(path) as f:
        defs = json.load(f)
    ids.update(str(s) for d in defs for s in d['spell_ids'])
print(','.join(sorted(ids)) if ids else '0')
")"
mysql -h 127.0.0.1 -u acore -pacore -N -B -e "
  SELECT cs.guid, cs.spell
  FROM acore_characters.character_spell cs
  JOIN acore_characters.characters c ON c.guid = cs.guid
  JOIN acore_auth.account a ON a.id = c.account
  WHERE cs.spell IN ($SPELL_COLLECTION_IDS)
    AND a.username NOT LIKE 'RNDBOT%';
" > "$KNOWN_SPELLS_TMP"
mysql -h 127.0.0.1 -u acore -pacore -N -B -e "
  SELECT
    c.guid,
    c.name,
    a.username,
    c.race,
    CASE c.race
      WHEN 1 THEN 'Human' WHEN 2 THEN 'Orc' WHEN 3 THEN 'Dwarf' WHEN 4 THEN 'Night Elf'
      WHEN 5 THEN 'Undead' WHEN 6 THEN 'Tauren' WHEN 7 THEN 'Gnome' WHEN 8 THEN 'Troll'
      WHEN 9 THEN 'Goblin' WHEN 10 THEN 'Blood Elf' WHEN 11 THEN 'Draenei'
      ELSE 'Unknown'
    END,
    c.class,
    CASE c.class
      WHEN 1 THEN 'Warrior' WHEN 2 THEN 'Paladin' WHEN 3 THEN 'Hunter' WHEN 4 THEN 'Rogue'
      WHEN 5 THEN 'Priest' WHEN 6 THEN 'Death Knight' WHEN 7 THEN 'Shaman' WHEN 8 THEN 'Mage'
      WHEN 9 THEN 'Warlock' WHEN 11 THEN 'Druid'
      ELSE 'Unknown'
    END,
    CASE
      WHEN c.race IN (1,3,4,7,11) THEN 'Alliance'
      WHEN c.race IN (2,5,6,8,9,10) THEN 'Horde'
      ELSE 'Unknown'
    END,
    c.level,
    c.money,
    COALESCE(cap.total_points, 0),
    COALESCE(cap.total_achievements, 0),
    c.totaltime
  FROM acore_characters.characters c
  JOIN acore_auth.account a ON a.id = c.account
  LEFT JOIN acore_characters.character_achievement_points cap ON cap.guid = c.guid
  WHERE a.username NOT LIKE 'RNDBOT%'
  ORDER BY c.totaltime DESC;
" | python3 -c "
import sys, json, datetime, os
from collections import defaultdict

def iso(unix_ts):
    try:
        ts = int(unix_ts)
    except (TypeError, ValueError):
        return None
    if ts <= 0:
        return None
    return datetime.datetime.utcfromtimestamp(ts).strftime('%Y-%m-%dT%H:%M:%SZ')

# Achievements carry their real completion date straight from
# character_achievement.date (Blizzard's own record) — no tracking needed.
achievements_by_guid = defaultdict(list)
with open('$ACHIEVEMENTS_TMP') as f:
    for line in f:
        line = line.rstrip('\n')
        if not line:
            continue
        guid, achievement_id, earned_unix = line.split('\t')
        achievements_by_guid[int(guid)].append({
            'id': int(achievement_id),
            'earned_at': iso(earned_unix),
        })

# Currently-equipped item entries per character (bag=0, slot 0-18 — actual
# gear, not bags/bank).
equipped_by_guid = defaultdict(set)
with open('$EQUIPPED_TMP') as f:
    for line in f:
        line = line.rstrip('\n')
        if not line:
            continue
        guid, item_entry = line.split('\t')
        equipped_by_guid[int(guid)].add(int(item_entry))

with open('$COLLECTION_GEAR_DEFS') as f:
    collection_gear_defs = json.load(f)

def detect_collection_gear(equipped_ids):
    # Earned when the character has at least one item from EVERY slot group
    # equipped right now (each slot group lists interchangeable item ids for
    # that slot — a 'Conquest'-suffixed variant and its plain counterpart, or
    # a Horde/Alliance pair sharing one display name).
    earned = []
    for gs in collection_gear_defs:
        if all(any(item_id in equipped_ids for item_id in group) for group in gs['slot_groups']):
            earned.append(gs['id'])
    return earned

# Known mount-learn spells per character (character_spell has no per-row
# timestamp, unlike character_achievement — that's why mounts use the same
# sticky-timestamp fallback as Gear below).
known_spells_by_guid = defaultdict(set)
with open('$KNOWN_SPELLS_TMP') as f:
    for line in f:
        line = line.rstrip('\n')
        if not line:
            continue
        guid, spell_id = line.split('\t')
        known_spells_by_guid[int(guid)].add(int(spell_id))

with open('$COLLECTION_MOUNTS_DEFS') as f:
    collection_mounts_defs = json.load(f)

with open('$COLLECTION_PETS_DEFS') as f:
    collection_pets_defs = json.load(f)

def detect_by_known_spell(known_spell_ids, defs):
    # Shared by Mounts and Pets: earned when the character knows ANY ONE of
    # its spell_ids — multi-color mounts (Netherwing Drake, Qiraji Battle
    # Tank) list every color's spell id and complete on any single color,
    # never requiring every color.
    earned = []
    for entry in defs:
        if any(spell_id in known_spell_ids for spell_id in entry['spell_ids']):
            earned.append(entry['id'])
    return earned

# Sticky, with the original earned_at preserved: once earned, a collection
# is never removed and its earned_at is never overwritten, even after the
# gear is swapped away. Read whatever was already published last run (if
# any) and carry its earned_at forward for anything still present.
def _earned_at_map(entries):
    # entries used to be bare ids (pre-earned_at); accept both
    return {
        (entry['id'] if isinstance(entry, dict) else entry):
            (entry.get('earned_at') if isinstance(entry, dict) else None)
        for entry in entries
    }

previous_collection_gear_by_guid = defaultdict(dict)
previous_collection_mounts_by_guid = defaultdict(dict)
previous_collection_pets_by_guid = defaultdict(dict)
prev_path = '$REPO_DATA_DIR/characters.json'
if os.path.exists(prev_path):
    try:
        with open(prev_path) as f:
            previous_data = json.load(f)
        for prev_char in previous_data.get('characters', []):
            prev_collections = prev_char.get('collections', {})
            previous_collection_gear_by_guid[prev_char['guid']] = _earned_at_map(prev_collections.get('gear', []))
            previous_collection_mounts_by_guid[prev_char['guid']] = _earned_at_map(prev_collections.get('mounts', []))
            previous_collection_pets_by_guid[prev_char['guid']] = _earned_at_map(prev_collections.get('pets', []))
    except (json.JSONDecodeError, OSError):
        pass  # first run, or an unreadable/corrupt previous file — start fresh

generated_at = datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')

characters = []
for line in sys.stdin:
    line = line.rstrip('\n')
    if not line:
        continue
    (guid, name, account, race, race_name, cls, class_name,
     faction, level, money, ap, ac, played) = line.split('\t')
    guid = int(guid)

    gear_earned_at = dict(previous_collection_gear_by_guid.get(guid, {}))
    for gear_id in detect_collection_gear(equipped_by_guid.get(guid, set())):
        gear_earned_at.setdefault(gear_id, generated_at)
    collection_gear = [
        {'id': gear_id, 'earned_at': earned_at}
        for gear_id, earned_at in sorted(gear_earned_at.items())
    ]

    known_spells = known_spells_by_guid.get(guid, set())

    mounts_earned_at = dict(previous_collection_mounts_by_guid.get(guid, {}))
    for mount_id in detect_by_known_spell(known_spells, collection_mounts_defs):
        mounts_earned_at.setdefault(mount_id, generated_at)
    collection_mounts = [
        {'id': mount_id, 'earned_at': earned_at}
        for mount_id, earned_at in sorted(mounts_earned_at.items())
    ]

    pets_earned_at = dict(previous_collection_pets_by_guid.get(guid, {}))
    for pet_id in detect_by_known_spell(known_spells, collection_pets_defs):
        pets_earned_at.setdefault(pet_id, generated_at)
    collection_pets = [
        {'id': pet_id, 'earned_at': earned_at}
        for pet_id, earned_at in sorted(pets_earned_at.items())
    ]

    characters.append({
        'guid': guid,
        'name': name,
        'account': account,
        'race_id': int(race),
        'race_name': race_name,
        'class_id': int(cls),
        'class_name': class_name,
        'faction': faction,
        'level': int(level),
        'money_copper': int(money),
        'achievement_points': int(ap),
        'achievement_count': int(ac),
        'played_time_seconds': int(played),
        'achievements': sorted(achievements_by_guid.get(guid, []), key=lambda a: a['id']),
        'collections': {
            'gear': collection_gear,
            'mounts': collection_mounts,
            'pets': collection_pets,
        },
    })

with open('$BACKUP_DIR/characters.json', 'w') as f:
    json.dump({'generated_at': generated_at, 'characters': characters}, f, indent=2)

public_characters = [{k: v for k, v in c.items() if k != 'account'} for c in characters]
with open('$REPO_DATA_DIR/characters.json', 'w') as f:
    json.dump({'generated_at': generated_at, 'characters': public_characters}, f, indent=2)

print(f'  characters.json: wrote {len(characters)} characters')
" || { echo "Failed: characters.json export"; exit 1; }
rm -f "$ACHIEVEMENTS_TMP" "$EQUIPPED_TMP" "$KNOWN_SPELLS_TMP"

echo "  Publishing characters.json to GitHub..."
(
  cd "$REPO_DATA_DIR" \
    && git add characters.json \
    && if ! git diff --cached --quiet; then
         git commit -m "Update character data $TIMESTAMP" \
           && git push origin main
       else
         echo "  No character data changes to publish."
       fi
) || echo "  Warning: failed to publish characters.json to GitHub (non-fatal)"

echo "  Compressing..."
gzip "$BACKUP_DIR"/*.sql || { echo "Failed to compress"; exit 1; }

echo "  Local backup complete: $BACKUP_DIR"

# ── STEP 2: Upload to Google Drive ───────────────────────────────────────────
echo
echo "[2/4] Uploading to Google Drive..."
rclone copy "$BACKUP_DIR" "$GDRIVE_REMOTE/backups/$TIMESTAMP" --progress \
  || { echo "Google Drive upload failed"; exit 1; }

# ── STEP 3: Screenshots ───────────────────────────────────────────────────────
echo
echo "[3/4] Syncing screenshots to Google Drive..."
rclone copy "$SCREENSHOT_SRC" "$GDRIVE_REMOTE/screenshots" --progress \
  || { echo "Google Drive screenshot sync failed"; exit 1; }

# ── STEP 4: Rotate old backups (count-based) ──────────────────────────────────
echo
echo "[4/4] Rotating old backups..."

echo "  Keeping latest $KEEP_LOCAL_COUNT local backups..."
ls -1dt "$FULL_BASE"/*/ | tail -n +$((KEEP_LOCAL_COUNT + 1)) | xargs -r rm -rf \
  && echo "  Local rotation done." \
  || echo "  Warning: local rotation had issues (non-fatal)"

echo "  Keeping latest $KEEP_DRIVE_COUNT Drive backups..."
DRIVE_DIRS=$(rclone lsf "$GDRIVE_REMOTE/backups/" --dirs-only | sort | head -n -$KEEP_DRIVE_COUNT)
if [ -n "$DRIVE_DIRS" ]; then
  echo "$DRIVE_DIRS" | while read -r dir; do
    rclone purge "$GDRIVE_REMOTE/backups/$dir" \
      && echo "  Deleted Drive backup: $dir" \
      || echo "  Warning: failed to delete $dir (non-fatal)"
  done
else
  echo "  No Drive backups to prune."
fi

# ── Summary ───────────────────────────────────────────────────────────────────
echo
echo "======================================="
echo "Backup Complete!"
echo "  Local: $BACKUP_DIR"
echo "  Drive: $GDRIVE_REMOTE/backups/$TIMESTAMP"
echo "  Drive screenshots: $GDRIVE_REMOTE/screenshots"
echo "======================================="
echo
echo "Progress:"
cat "$BACKUP_DIR/playtime_by_character.txt"
echo
echo "Backup contents:"
ls -lh "$BACKUP_DIR"
